class Solution {
    public boolean isBalanced(String line) {
        // Stack of openers (latest opener must close first)
        // Closer must meet opener of its kind on top of stack
        // Balanced = nothing left unmatched at end
        Deque<Character> stack = new ArrayDeque<>();
        for (char c : line.toCharArray()) {
            // opener waits for its closer
            if (c == '(' || c == '[' || c == '{') {
                stack.push(c);
                continue;
            }
            // empty stack = closer has no opener
            if (stack.isEmpty()) return false;
            char open = stack.pop();
            // popped opener must be this closer's kind
            if ((c == ')' && open != '(') || (c == ']' && open != '[') || (c == '}' && open != '{')) return false;
        }
        // leftover openers never closed
        return stack.isEmpty();
    }
}

