class Solution {
public:
    bool isBalanced(string line) {
        // Delete adjacent matched pairs until none are left
        // Balanced = line ends up empty
        // removing inner pair can expose outer pair, so repeat until pass removes nothing
        while (true) {
            // line after this pass
            string next;
            for (size_t i = 0; i < line.size(); i++) {
                // matched pair is dropped (skip both chars)
                if (i + 1 < line.size() && isPair(line[i], line[i + 1])) {
                    i++;
                    continue;
                }
                next += line[i];
            }
            // nothing removed, so empty = every bracket was matched
            if (next.size() == line.size()) return line.empty();
            line = next;
        }
    }
private:
    static bool isPair(char a, char b) {
        return (a == '(' && b == ')') || (a == '[' && b == ']') || (a == '{' && b == '}');
    }
};

