class Solution {
    public int[] daysUntilWarmer(int[] temps) {
        // Stack of days still waiting for warmer day
        // Temps never rise from bottom to top
        // Warmer day answers every colder day on top of stack
        int n = temps.length;
        // 0 = no warmer day ahead
        int[] ans = new int[n];
        int[] waiting = new int[n];
        // stack size (next free slot)
        int top = 0;
        for (int i = 0; i < n; i++) {
            // today is first warmer day for top day
            while (top > 0 && temps[waiting[top - 1]] < temps[i]) {
                int colder = waiting[--top];
                ans[colder] = i - colder;
            }
            // today waits for own warmer day
            waiting[top++] = i;
        }
        return ans;
    }
}

