class Solution {
    public int largestBanner(int[] heights) {
        // Try each building as shortest in banner
        // Stretch both ways over neighbours at least as tall
        // Area = height * width, keep best
        int n = heights.length, best = 0;
        for (int i = 0; i < n; i++) {
            // banner [lo, hi] starts as building i alone
            int h = heights[i], lo = i, hi = i;
            // stretch left edge
            while (lo > 0 && heights[lo - 1] >= h) lo--;
            // stretch right edge
            while (hi < n - 1 && heights[hi + 1] >= h) hi++;
            // width counts both ends
            best = Math.max(best, h * (hi - lo + 1));
        }
        return best;
    }
}

