class Solution {
    public int largestBanner(int[] heights) {
        // Banner height = shortest bar in it
        // rising (stack of bar indexes, heights increasing)
        // Shorter bar pops taller ones and scores each
        // Popped bar's span ends at stack neighbour (left) and i (right)
        int n = heights.length;
        Deque<Integer> rising = new ArrayDeque<>();
        int best = 0;
        for (int i = 0; i <= n; i++) {
            // 0 past end pops every remaining bar
            int current;
            if (i < n) {
                current = heights[i];
            } else {
                current = 0;
            }
            // top bar at least as tall as current, so its span ends at i - 1
            while (!rising.isEmpty() && heights[rising.peek()] >= current) {
                int topIndex = rising.pop();
                int height = heights[topIndex];
                // nearest shorter bar on left (-1 if none)
                int leftWall;
                if (!rising.isEmpty()) {
                    leftWall = rising.peek();
                } else {
                    leftWall = -1;
                }
                // width = bars strictly between leftWall and i
                int width = i - leftWall - 1;
                int area = height * width;
                if (area > best) {
                    best = area;
                }
            }
            // top now shorter than current, so heights stay rising
            rising.push(i);
        }
        return best;
    }
}

